      : [decode(pair.slice(0, at)), decode(pair.slice(at + 1))]
  }
  const listOf = text => {
    const body = text.startsWith('?') ? text.slice(1) : text
    return body.split('&').filter(pair => pair !== '').map(pairOf)
  }
  class URLSearchParams {
    constructor(init = '') {
      let list = []
      if (typeof init === 'string') {
        list = listOf(init)
      } else if (isObject(init)) {
        if (typeof init[Symbol.iterator] === 'function') {
          for (const [k, v] of init) list.push([String(k), String(v)])
        } else {
          for (const key of Object.keys(init)) {
            list.push([key, String(init[key])])
          }
        }
      }
      paramsState.set(this, { list, onChange: null })
    }
    #changed() {
      const s = paramsState.get(this)
      if (s.onChange !== null) s.onChange(this.toString())
    }
    #matches(name, value) {
      return ([k, v]) =>
        k === String(name) && (value === undefined || v === String(value))
    }
    append(name, value) {
      paramsState.get(this).list.push([String(name), String(value)])
      this.#changed()
    }
    delete(name, value) {
      const s = paramsState.get(this)
      const matches = this.#matches(name, value)
      s.list = s.list.filter(pair => !matches(pair))
      this.#changed()
    }
    get(name) {
      const found = paramsState.get(this).list.find(([k]) => k === String(name))
      return found === undefined ? null : found[1]
    }
    getAll(name) {
      return paramsState.get(this).list
        .filter(([k]) => k === String(name))
        .map(([, v]) => v)
    }
    has(name, value) {
      return paramsState.get(this).list.some(this.#matches(name, value))
    }
    set(name, value) {
      const s = paramsState.get(this)
      const key = String(name)
      const at = s.list.findIndex(([k]) => k === key)
      s.list = s.list.filter(([k], i) => k !== key || i === at)
      if (at === -1) s.list.push([key, String(value)])
      else s.list[at] = [key, String(value)]
      this.#changed()
    }
    sort() {
      const s = paramsState.get(this)
      s.list.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      this.#changed()
    }
    forEach(fn, self) {
      for (const [k, v] of paramsState.get(this).list) fn.call(self, v, k, this)
    }
    entries() {
      const pairs = paramsState.get(this).list.map(([k, v]) => [k, v])
      return pairs[Symbol.iterator]()
    }
    keys() {
      return paramsState.get(this).list.map(([k]) => k)[Symbol.iterator]()
    }
    values() {
      return paramsState.get(this).list.map(([, v]) => v)[Symbol.iterator]()
    }
    [Symbol.iterator]() { return this.entries() }
    get size() { return paramsState.get(this).list.length }
    toString() {
      return paramsState.get(this).list
        .map(([k, v]) => encode(k) + '=' + encode(v))
        .join('&')
    }
    get [Symbol.toStringTag]() { return 'URLSearchParams' }
  }
  const urlState = new WeakMap()
  const PARTS = [
    'href', 'origin', 'protocol', 'username', 'password', 'host', 'hostname',
    'port', 'pathname', 'search', 'hash',
  ]
  const parse = (input, base) => {
    const json = guarded(helpers.parseUrl)(
      String(input),
      base === undefined ? undefined : String(base),
    )
    if (json === null) throw err('Invalid URL: ' + String(input))
    return JSON.parse(json)
  }
  const setPart = (url, part, value) => {
    const s = urlState.get(url)
    const json = guarded(helpers.setUrlPart)(s.parts.href, part, String(value))
    if (json === null) return false
    s.parts = JSON.parse(json)
    return true
  }
  const paramsFor = (url, search) => {
    const params = new URLSearchParams(search)
    paramsState.get(params).onChange = text => { setPart(url, 'search', text) }
    return params
  }
  class URL {
    constructor(input, base) {
      const parts = parse(input, base)
      urlState.set(this, { parts, params: paramsFor(this, parts.search) })
    }
    static canParse(input, base) {
      try { parse(input, base); return true } catch { return false }
    }
    static parse(input, base) {
      try { return new URL(input, base) } catch { return null }
    }
    get searchParams() { return urlState.get(this).params }
    toString() { return urlState.get(this).parts.href }
    toJSON() { return urlState.get(this).parts.href }
    get [Symbol.toStringTag]() { return 'URL' }
  }
  for (const part of PARTS) {
    Object.defineProperty(URL.prototype, part, {
      get() { return urlState.get(this).parts[part] },
      set(value) {
        if (part === 'origin' || !setPart(this, part, value)) return
        const s = urlState.get(this)
        paramsState.get(s.params).list = listOf(s.parts.search)
      },
      enumerable: true,
      configurable: true,
    })
  }
  define('URL', URL)
  define('URLSearchParams', URLSearchParams)

  // -- atob / btoa
  define('atob', text => guarded(helpers.atob)(String(text)))
  define('btoa', text => guarded(helpers.btoa)(String(text)))

  // -- structuredClone (the environment's own walk: plain data, Date, RegExp,
  // Map, Set, buffers)
  const uncloneable = () =>
    err('The object can not be cloned.', 'DataCloneError')
  const cloneInto = (value, seen) => {
    if (typeof value !== 'object' || value === null) {
      if (typeof value === 'function' || typeof value === 'symbol') {
        throw uncloneable()
      }
      return value
    }
    if (seen.has(value)) return seen.get(value)
    if (Array.isArray(value)) {
      const out = []
      seen.set(value, out)
      for (const item of value) out.push(cloneInto(item, seen))
      return out
    }
    if (value instanceof Date) return new Date(value.getTime())
    if (value instanceof RegExp) return new RegExp(value.source, value.flags)
    if (value instanceof Map) {
      const out = new Map()
      seen.set(value, out)
      for (const [k, v] of value) {
        out.set(cloneInto(k, seen), cloneInto(v, seen))
      }
      return out
    }
    if (value instanceof Set) {
      const out = new Set()
      seen.set(value, out)
      for (const v of value) out.add(cloneInto(v, seen))
      return out
    }
    if (value instanceof ArrayBuffer) return value.slice(0)
    if (value instanceof DataView) {
      const end = value.byteOffset + value.byteLength
      return new DataView(value.buffer.slice(value.byteOffset, end))
    }
    if (ArrayBuffer.isView(value)) return new value.constructor(value)
    if (value instanceof Error) return err(value.message, value.name)
    const proto = Object.getPrototypeOf(value)
    if (
      proto !== null &&
      proto !== Object.prototype &&
      Object.getPrototypeOf(proto) !== null
    ) {
      throw uncloneable()
    }
    const out = {}
    seen.set(value, out)
    for (const key of Object.keys(value)) out[key] = cloneInto(value[key], seen)
    return out
  }
  define('structuredClone', value => cloneInto(value, new Map()))

  // -- crypto, performance
  const algorithmName = algorithm =>
    typeof algorithm === 'string'
      ? algorithm
      : isObject(algorithm) ? String(algorithm.name) : String(algorithm)
  const subtle = Object.freeze({
    __proto__: null,
    // An async function of the environment's: the promise is the
    // environment's own, and the host's rejection (an unknown algorithm) an
    // Error of the environment's.
    digest: async (algorithm, data) => {
      const name = algorithmName(algorithm)
      try {
        return await helpers.digestInto(name, data, n => new ArrayBuffer(n))
      } catch (error) {
        throw fromHost(error)
      }
    },
  })
  define('crypto', Object.freeze({
    __proto__: null,
    subtle,
    randomUUID: () => guarded(helpers.randomUUID)(),
    getRandomValues: array => {
      guarded(helpers.fillRandom)(array)
      return array
    },
  }))
  define('performance', Object.freeze({
    __proto__: null,
    now: () => guarded(helpers.now)(),
  }))

  // -- JSX (render-jsx/): the classic runtime's h and Fragment, and the
  // capitalised tags
  const jsx = ${

}
  define('h', jsx.h)
  define('Fragment', jsx.Fragment)
  define('Box', 'Box')
  define('Text', 'Text')
  define('Button', 'Button')
  define('Input', 'Input')
  define('Select', 'Select')
  define('Link', 'Link')

  return Object.freeze({
    __proto__: null,
    makeSignal,
    makeError: (name, message) => err(message, name),
    relaySignal: (signal, abort) => {
      const relay = () => {
        const reason = signal.reason
        if (reason instanceof Error) abort(reason.name, reason.message)
        else if (reason === undefined) {
          abort('AbortError', 'This operation was aborted')
        } else abort('AbortError', String(reason))
      }
      if (signal.aborted) relay()
      else signal.addEventListener('abort', relay, { once: true })
      return () => signal.removeEventListener('abort', relay)
    },
  })
})

// Non-storybook `package` adapter. Bundles dist/ when present (the authoritative
// component list comes from shipped .d.ts; with no dist it synthesizes an
// entry from src/ as a last resort) and opportunistically enriches each
// component from src/ - JSDoc and dir-derived group. Every enrichment miss
// degrades to the plain-dist behaviour.
//
// Discovery is heuristic-based; each heuristic has a `.design-sync/config.json`
// override (ASSUMPTION comments below name them) so repos that don't match the
// defaults write config, not code. `componentSrcMap` is the single override
// knob for component inclusion: non-null value = add/pin src path, null =
// exclude a .d.ts-exported internal.

import { existsSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { Project, Node, ts } from 'ts-morph';
import { leadingJsdoc, readText, slash, walk } from './common.mjs';
import { resolveDistEntry } from './bundle.mjs';
import { exportedNames, isComponentName } from './dts.mjs';

const NON_IMPL_RX = /\.(stories|test|spec)\./;
const SRC_IMPL_RX = /\.(tsx|jsx)$/;
// Dir names that don't usefully group components - skip so the emitted path
// is `components/<group>/<Name>` not `components/components/<Name>`.
const GENERIC_DIR = new Set(['components', 'component', 'src', 'lib', 'ui', 'packages', 'react']);
const slug = (s) => s.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'general';

// No .d.ts -> scan src files for PascalCase value exports via ts-morph.
function deriveComponentsFromSrc(srcFiles) {
  const project = new Project({
    skipAddingFilesFromTsConfig: true,
    compilerOptions: { jsx: ts.JsxEmit.Preserve, allowJs: true, skipLibCheck: true },
  });
  const seen = new Set();
  for (const p of srcFiles) {
    if (NON_IMPL_RX.test(p) || !SRC_IMPL_RX.test(p)) continue;
    const sf = project.addSourceFileAtPathIfExists(p);
    if (!sf) continue;
    for (const [name, decls] of sf.getExportedDeclarations()) {
      // `export default function Button()` is keyed as 'default' - recover
      // the declared name from the function/class node.
      const real = name === 'default'
        ? decls.map((d) => d.getName?.()).find((n) => n && n !== 'default')
        : name;
      if (!real || !/^[A-Z][A-Za-z0-9]*$/.test(real)) continue;
      if (decls.some((d) => Node.isVariableDeclaration(d) || Node.isFunctionDeclaration(d) || Node.isClassDeclaration(d))) {
        seen.add(real);
      }
    }
  }
  return [...seen].sort().map((name) => ({ name, group: 'general' }));
}

export async function resolvePackage(ctx) {
  const { PKG_DIR, pkgJson, ENTRY_OVERRIDE, PKG, OUT, cfg } = ctx;
  const srcMap = cfg.componentSrcMap ?? {};

  // -- 1. src/ discovery (best-effort; feeds enrichment + synth-entry fallback).
  // ASSUMPTION: source root is first of src/ | lib/ | components/. Override: cfg.srcDir.
  const srcRoot = [cfg.srcDir, 'src', 'lib', 'components']
    .map((d) => d && resolve(PKG_DIR, d))
    .find((d) => d && existsSync(d));
  const srcFiles = srcRoot ? walk(srcRoot, (n) => /\.(tsx|jsx|mdx?)$/.test(n)) : [];

  // -- 2. entry: dist if it exists, else synthesize from src/ (last resort).
  let entry = resolveDistEntry({ pkgDir: PKG_DIR, pkgJson, override: ENTRY_OVERRIDE, pkgName: PKG, soft: true });
  let synthEntry = false;
  if (!entry) {
    if (!srcRoot) {
      console.error(`[NO_DIST] ${PKG} has no built entry and no src/ to synthesize from \u2014 run its build.`);
      process.exit(1);
    }
    const comps = srcFiles.filter((p) => SRC_IMPL_RX.test(p) && !NON_IMPL_RX.test(p));
    entry = join(OUT, '.pkg-entry.mjs');
    writeFileSync(entry, comps.map((p) => `export * from ${JSON.stringify(p)};`).join('\n') + '\n');
    synthEntry = true;
    console.error(
      `[NO_DIST] no built entry \u2014 synthesizing from ${comps.length} src files (run the package's build for best results)`,
    );
  }

  // -- 3. component list: from shipped .d.ts (authoritative when dist exists).
  // ASSUMPTION: components = PascalCase value exports in the .d.ts tree.
  // Override: cfg.componentSrcMap (non-null adds/pins, null excludes).
  const exported = exportedNames(PKG_DIR, pkgJson);
  const names = new Set([...exported].filter(isComponentName));
  for (const [k, v] of Object.entries(srcMap)) {
    if (v === null) { names.delete(k); continue; }
    // Names reach `<script>` blocks in the emitted HTML - reject anything
    // that isn't a plain PascalCase identifier.
    if (!/^[A-Z][A-Za-z0-9]*$/.test(k)) {
      console.error(`[CONFIG] componentSrcMap: "${k}" is not a valid component name (PascalCase identifiers only)`);
      continue;
    }
    names.add(k);
  }
  let components = [...names].sort().map((name) => ({ name, group: 'general' }));
  if (!components.length && synthEntry) {
    components = deriveComponentsFromSrc(srcFiles).filter((c) => srcMap[c.name] !== null);
  }
  if (!components.length) {
    if (cfg.cssEntry || existsSync(join(PKG_DIR, 'styles.css'))) {
      console.error('[ZERO_MATCH] no component exports \u2014 treating as tokens-only DS');
      return { shape: 'package', entry, components: [], tokensOnly: true };
    }
    console.error(`[ZERO_MATCH] no PascalCase exports in ${PKG} and no styles \u2014 nothing to sync`);
    process.exit(1);
  }

  // -- 4. src/ enrichment per component. Every miss degrades to plain-dist.
  if (srcRoot) {
    for (const c of components) {
      // Pinned via config -> skip fuzzy-find entirely.
      let hit = typeof srcMap[c.name] === 'string' ? slash(resolve(PKG_DIR, srcMap[c.name])) : null;
      if (!hit) {
        // ASSUMPTION: <Name>.tsx | <name>/<name>.tsx | <Name>/index.tsx |
        // <kebab-name>.tsx, case-insensitive; dir-match ranks above
        // bare-file match, then prefer one that actually exports `c.name`.
        // Override: cfg.componentSrcMap.
        const kebab = c.name.replace(/([a-z0-9])([A-Z])/g, '$1-$2');
        const nameRx = new RegExp(
          `(?:^|/)(?:${c.name}/(?:index|${c.name})\\.(tsx|jsx)|(?:${c.name}|${kebab})\\.(tsx|jsx))$`,
          'i',
        );
        const hits = srcFiles
          .filter((p) => nameRx.test(p) && !NON_IMPL_RX.test(p))
          .sort(
            (a, b) =>
              (b.toLowerCase().includes(`/${c.name.toLowerCase()}/`) ? 1 : 0) -
              (a.toLowerCase().includes(`/${c.name.toLowerCase()}/`) ? 1 : 0),
          );
        const exportRx = new RegExp(`export\\s+(?:default\\s+)?(?:const|let|var|function|class)\\s+${c.name}\\b`);
        hit = hits.find((p) => exportRx.test(readText(p))) ?? hits[0];
      }
      if (!hit || !existsSync(hit)) continue;
      c.srcPath = hit;
      c.doc = leadingJsdoc(readText(hit), c.name) || undefined;
      // group = last src/ path segment that isn't the component's own dir or
      // a generic container name - else JSDoc @category - else 'general'.
      c.group = slug(
        slash(relative(srcRoot, dirname(hit)))
          .split('/')
          .filter((s) => s && s.toLowerCase() !== c.name.toLowerCase() && !GENERIC_DIR.has(s.toLowerCase()))
          .at(-1)
        || (c.doc && /@category\s+(\S+)/.exec(c.doc)?.[1])
        || 'general',
      );
    }
  }

  console.error(
    `  package: ${components.length} components` +
      (srcRoot ? ` (${components.filter((c) => c.srcPath).length} src-matched)` : ' (no src/ \u2014 dist-only)'),
  );
  return { shape: 'package', entry, components, synthEntry, exported };
}

// One chromium page visit against the reference storybook-static: fiber-walk
// provider detection. Fallback diagnostic for when
// the .storybook/preview decorator bundle fails (or doesn't exist) and
// previews show context/provider errors - it infers the provider chain the
// repo's own storybook wraps stories in, as a cfg.provider suggestion.
// Provider match is name-based (displayName/name) - the storybook page's
// React is a separate bundled copy, so identity-matching against our
// _ds_bundle.js wouldn't work.
//
// Standalone usage (prints a cfg.provider suggestion as JSON on stdout):
//   node storybook/probe.mjs --storybook-static .design-sync/sb-reference \
//     [--story-id <id>] [--names Button,ThemeProvider,...]

import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { serveDir } from './http-serve.mjs';

// Walk fibers from the story's leaf node upward, recording every named
// component. `names` (when non-empty) filters to that set - pass the DS's
// exported names so story-internal wrappers don't pollute the chain; with no
// filter, every PascalCase-named fiber is recorded (diagnostic mode).
const FIBER_WALK_STORE = `((names) => {
  const set = new Set(names);
  const root = document.querySelector('#storybook-root') || document.querySelector('#root');
  // Descend to the leaf, skipping injected metadata elements \u2014 CSS-in-JS
  // runtimes often put a <style>/<script> as the first child, which has no
  // fiber and would dead-end provider detection.
  const SKIP = /^(STYLE|SCRIPT|LINK|META|TEMPLATE)$/;
  const content = (el) => [...el.children].find((c) => !SKIP.test(c.tagName));
  let n = root && content(root);
  while (n) { const c = content(n); if (!c) break; n = c; }
  if (!n || n === root) return (window.__dsChain = []).length;
  const fkey = Object.keys(n).find((k) => k.startsWith('__reactFiber$'));
  let fiber = fkey ? n[fkey] : null;
  const out = [];
  while (fiber) {
    const t = fiber.type || fiber.elementType;
    const nm = t && (t.displayName || t.name);
    if (nm && /^[A-Z]/.test(nm) && (set.size === 0 || set.has(nm))) out.push({ component: nm, liveProps: fiber.memoizedProps || {} });
    fiber = fiber.return;
  }
  return (window.__dsChain = out.reverse()).length;
})`;

const RESOLVE_PROPS = `(() => {
  // Primitives pass through; objects become a $hint of their top-level keys
  // (the user sets the real value via cfg.provider).
  const ser = (v) => {
    if (v == null || typeof v !== 'object') return typeof v === 'function' ? undefined : v;
    if (v.$$typeof) return undefined;
    return { $hint: Object.keys(v).slice(0, 5).map((k) => String(k).replace(/[^\\w]/g, '_')).join(',') };
  };
  // The chain runs outermost-first. Keep only the outermost component plus
  // any immediately-nested one whose name suggests it's part of the provider
  // shell (Provider/Theme/Root/App) \u2014 layout components like Box/Grid deeper
  // in are story-specific, not provider.
  const chain = window.__dsChain || [];
  const shell = chain.slice(0, 1).concat(
    chain.slice(1).filter((c, i) => i < 1 && /Provider|Theme|Root|App|Config|Styles|Reset|Base/i.test(c.component)),
  );
  return shell.map((c) => {
    const props = {};
    for (const [k, v] of Object.entries(c.liveProps)) {
      if (k === 'children') continue;
      const s = ser(v);
      if (s !== undefined) props[k] = s;
    }
    return { component: c.component, props };
  });
})`;

// `sbStatic` is served directly - the reference storybook build, not an
// uploaded artifact.
export async function probe({ sbStatic, firstStoryId, exportedNames = [] }) {
  let pw;
  try { pw = await import('playwright'); }
  catch {
    console.error('[NO_CHROMIUM] provider detection skipped \u2014 set cfg.provider manually if the DS needs one');
    return { provider: null };
  }
  const { srv, port } = await serveDir(sbStatic);
  let browser;
  try {
    browser = await pw.chromium.launch(
      process.env.DS_CHROMIUM_PATH ? { executablePath: process.env.DS_CHROMIUM_PATH } : {},
    );
    const page = await browser.newPage();
    await page.goto(`http://127.0.0.1:${port}/iframe.html?id=${encodeURIComponent(firstStoryId)}&viewMode=story`, { waitUntil: 'networkidle', timeout: 30_000 });
    // Storybook 7+ renders into #storybook-root; v6 into #root. Wait for
    // CONTENT, not any child - CSS-in-JS runtimes inject <style> first and
    // waitForSelector locks onto the first match.
    await page.waitForSelector(':is(#storybook-root, #root) > :not(style,script,link,meta,template)', { timeout: 10_000 }).catch(() => {});
    await page.evaluate(`(${FIBER_WALK_STORE})(${JSON.stringify(exportedNames)})`).catch(() => 0);
    const chain = await page.evaluate(`(${RESOLVE_PROPS})()`).catch(() => []);
    const provider = chain.length
      ? chain.reduceRight((inner, p) => ({ component: p.component, props: p.props, ...(inner ? { inner } : {}) }), null)
      : null;
    if (provider) console.error(`[PROVIDER_DETECTED] ${chain.map((p) => p.component).join(' > ')}`);
    return { provider };
  } catch (e) {
    console.error(`  ! probe: ${String(e).split('\n')[0]}`);
    return { provider: null };
  } finally {
    await browser?.close().catch(() => {});
    srv.close();
  }
}

// -- standalone CLI ---------------------------------------------------------
if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  const argv = process.argv.slice(2);
  const flag = (n, d) => { const i = argv.indexOf(`--${n}`); return i < 0 ? d : argv[i + 1]; };
  const sbStatic = flag('storybook-static') && resolve(flag('storybook-static'));
  if (!sbStatic || !existsSync(join(sbStatic, 'iframe.html'))) {
    console.error('usage: node storybook/probe.mjs --storybook-static <dir> [--story-id <id>] [--names A,B]');
    process.exit(2);
  }
  let storyId = flag('story-id');
  if (!storyId) {
    const idx = JSON.parse(readFileSync(join(sbStatic, 'index.json'), 'utf8'));
    storyId = Object.values(idx.entries ?? idx.stories ?? {}).find((e) => !e.type || e.type === 'story')?.id;
  }
  if (!storyId) { console.error('no story entries in index.json \u2014 pass --story-id'); process.exit(2); }
  const names = (flag('names') ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const { provider } = await probe({ sbStatic, firstStoryId: storyId, exportedNames: names });
  // The cfg.provider suggestion - paste into .design-sync/config.json after
  // resolving each $hint: literals for small scalars; for data the repo
  // already owns (locale JSON, theme objects), prefer a 2-line module via
  // cfg.extraEntries referenced with {"$ref": "<export>"} (repo files need
  // an explicit ./ or ../ package-relative entry; bare names resolve from
  // node_modules) - an inlined copy duplicates into every card and rots
  // when the source file changes, so anything sizable or evolving belongs
  // behind a $ref.
  console.log(JSON.stringify({ provider }, null, 2));
  process.exit(0);
}

// Shared by probe.mjs, compare.mjs, and package-capture.mjs. Kept standalone
// (node builtins only) so serving files never drags in the build toolchain
// (esbuild, ts-morph).
// Also runnable directly - `node http-serve.mjs <dir>` serves <dir> and
// prints the URL (used for the human review pass over .review.html).

import { existsSync, readFileSync, statSync } from 'node:fs';
import { createServer } from 'node:http';
import { extname, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.png': 'image/png' };

export function serveDir(root) {
  const rootAbs = resolve(root) + sep;
  const srv = createServer((req, res) => {
    let pathname, p;
    try {
      pathname = decodeURIComponent(new URL(req.url, 'http://x').pathname);
      p = resolve(root, '.' + pathname);
    } catch { res.statusCode = 400; return res.end(); }
    // 200 on / so a caller can goto('/') to establish a same-origin page
    // before setContent() (-> fonts load same-origin, no CORS header needed).
    if (pathname === '/') { res.setHeader('Content-Type', 'text/html'); return res.end('<!doctype html>'); }
    if (!p.startsWith(rootAbs) || !existsSync(p) || !statSync(p).isFile()) { res.statusCode = 404; return res.end(); }
    res.setHeader('Content-Type', MIME[extname(p)] ?? 'application/octet-stream');
    res.end(readFileSync(p));
  });
  return new Promise((r) => srv.listen(0, '127.0.0.1', () => r({ srv, port: srv.address().port })));
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  const { port } = await serveDir(process.argv[2] ?? '.');
  console.log(`serving ${resolve(process.argv[2] ?? '.')} at http://127.0.0.1:${port}/ (Ctrl-C to stop)`);
}

// Source-shape detection - shared by both adapters so cfg.shape can override
// the result without either shape's lib importing the other.

import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { ls } from './common.mjs';

// Enumerate .storybook/ config dirs under root (depth-limited, skips
// node_modules). Some DSes use `storybook/` (no dot) - match any dir with a
// main.* file.
export function findStorybookDirs(root, depth = 4) {
  const out = [];
  const isConfigDir = (p) =>
    ['ts', 'js', 'mjs', 'cjs'].some((e) => existsSync(join(p, `main.${e}`)));
  (function walk(d, lvl) {
    if (lvl > depth || !existsSync(d)) return;
    for (const e of ls(d, { withFileTypes: true })) {
      if (!e.isDirectory() || e.name === 'node_modules') continue;
      const p = join(d, e.name);
      if ((e.name === '.storybook' || e.name === 'storybook') && isConfigDir(p)) out.push(p);
      else walk(p, lvl + 1);
    }
  })(root, 0);
  return out;
}

export function detectShape({ INPUTS, SB_STATIC, SB_CONFIG_DIR }) {
  if (SB_STATIC || SB_CONFIG_DIR) {
    console.error(`[DETECT] shape=storybook (explicit ${SB_STATIC ? '--storybook-static' : '--storybook-config'})`);
    return 'storybook';
  }
  const found = findStorybookDirs(INPUTS, 4);
  const shape = found.length ? 'storybook' : 'package';
  console.error(`[DETECT] searched ${INPUTS} (depth 4), found .storybook at [${found.join(', ')}] \u2192 shape=${shape}`);
  return shape;
}

// Storybook-only CSS fallbacks - storybook-static's iframe.html is the source
// for both the compiled-stylesheet fallback (when _ds_bundle.css is a
// bundler-resolve-only stub) and remote webfont <link> scraping.

import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';

// Brand fonts shipped via .storybook/preview-head.html land inline in the
// built iframe.html, often as base64 data-URI @font-face that no filename
// search finds. Harvest faces that are FULLY self-contained (every src is a
// data: URI - storybook's own UI fonts use file URLs and are skipped) for
// families nothing else shipped.
export function inlineFontFacesFromStorybook(sbStatic, existingRules) {
  if (!sbStatic) return [];
  let html;
  try { html = readFileSync(join(sbStatic, 'iframe.html'), 'utf8'); } catch { return []; }
  const familyOf = (block) => /font-family:\s*['"]?([^'";}]+)/i.exec(block)?.[1].trim().toLowerCase();
  const have = new Set(existingRules.map(familyOf).filter(Boolean));
  const out = [];
  for (const m of html.matchAll(/@font-face\s*\{[^}]*\}/gi)) {
    const block = m[0];
    const urls = [...block.matchAll(/url\(\s*['"]?([^'")]+)/gi)].map((u) => u[1]);
    if (!urls.length || !urls.every((u) => u.startsWith('data:'))) continue;
    const fam = familyOf(block);
    if (!fam || have.has(fam)) continue;
    out.push(block);
  }
  if (out.length) console.error(`  [FONTS_FROM_PREVIEW_HEAD] harvested ${out.length} data-URI @font-face rule(s) from the storybook reference`);
  return out;
}

// Utility-CSS / CSS-in-JS DSes often ship a dist/styles.css
// that's a stub `@import "@scope/styles"` meant for a bundler to resolve.
export function isPlaceholderCss(p) {
  if (!existsSync(p)) return false;
  const sz = statSync(p).size;
  if (sz > 500) return false;
  const txt = readFileSync(p, 'utf8');
  // Only @import/@charset/comments/whitespace -> no real rules.
  const stripped = txt.replace(/\/\*[\s\S]*?\*\//g, '').replace(/@(import|charset)\b[^;]*;/g, '').trim();
  return stripped.length === 0;
}

// If bundleCss is a placeholder stub, replace it with storybook-static's own
// compiled CSS (the largest local <link rel=stylesheet> in iframe.html).
// Relative url()s are NOT rewritten - sbStatic isn't uploaded, so pointing
// into it would break post-upload. They'll 404 in the preview (images missing)
// but class rules still apply. Returns the new srcDir for extractFonts, which
// DOES copy font files into the bundle.
export function fallbackCssFromStorybook({ bundleCss, sbStatic, out }) {
  // A MISSING _ds_bundle.css counts too - DSes that ship styles in a sibling
  // package (compiled JS imports no CSS) emit no css file at all.
  if ((existsSync(bundleCss) && !isPlaceholderCss(bundleCss)) || !sbStatic || !existsSync(join(sbStatic, 'iframe.html'))) return null;
  const iframeHtml = readFileSync(join(sbStatic, 'iframe.html'), 'utf8');
  const links = [...iframeHtml.matchAll(/<link\b[^>]*>/gi)]
    .map((m) => m[0])
    .filter((t) => /\brel\s*=\s*["']stylesheet["']/i.test(t))
    .map((t) => t.match(/\bhref\s*=\s*["']([^"']+)["']/i)?.[1])
    .filter((h) => h && !/^(https?:|\/\/)/.test(h))
    .map((h) => join(sbStatic, h.replace(/^\.\//, '')))
    .filter((p) => p.startsWith(sbStatic + sep) && existsSync(p))
    .sort((a, b) => statSync(b).size - statSync(a).size);
  if (links[0]) {
    const was = existsSync(bundleCss) ? `a ${statSync(bundleCss).size}B placeholder` : 'missing';
    const kb = (statSync(links[0]).size / 1024).toFixed(0);
    const srcDir = dirname(links[0]);
    const css = readFileSync(links[0], 'utf8');
    const assets = [...new Set([...css.matchAll(/url\(\s*(['"]?)(?!data:|https?:|\/\/|\/)([^'")]+)\1\s*\)/gi)].map((m) => m[2]))];
    writeFileSync(bundleCss, css);
    console.error(`[CSS_FROM_STORYBOOK] _ds_bundle.css was ${was} \u2014 replaced with ${relative(out, links[0])} (${kb} KB).`);
    if (assets.length) {
      console.error(`[CSS_ASSETS] ${assets.length} relative url() ref(s) in the fallback CSS won't resolve post-upload (fonts are copied separately via extractFonts; images will 404): ${assets.slice(0, 5).join(', ')}${assets.length > 5 ? ', \u2026' : ''}`);
    }
    return srcDir;
  }
  console.error(`[CSS_PLACEHOLDER] _ds_bundle.css is missing or a stub (@import-only, <500B) and no storybook CSS found to fall back to \u2014 set cfg.cssEntry to the compiled stylesheet.`);
  return null;
}

// Remote stylesheet links (webfonts, etc.) from the storybook iframe. CSS-in-JS
// DSes emit no static stylesheet, but commonly inject a remote webfont <link>
// via .storybook/preview-head.html - that link
// is then the ONLY static style source. Returns absolute URLs to @import url().
export function scrapeRemoteImports(sbStatic) {
  if (!sbStatic || !existsSync(join(sbStatic, 'iframe.html'))) return [];
  const iframeHtml = readFileSync(join(sbStatic, 'iframe.html'), 'utf8');
  const out = [...new Set(
    [...iframeHtml.matchAll(/<link\b[^>]*>/gi)]
      .map((m) => m[0])
      .filter((t) => /\brel\s*=\s*["']stylesheet["']/i.test(t))
      .map((t) => t.match(/\bhref\s*=\s*["']([^"']+)["']/i)?.[1])
      .filter((h) => h && /^(https?:|\/\/)/.test(h))
      .map((h) => (h.startsWith('//') ? 'https:' + h : h)),
  )];
  if (out.length) {
    console.error(`  remote stylesheet(s) from storybook: ${out.length} \u2192 styles.css @import url(...)`);
  }
  return out;
}

// generatePreviewSource (storybook shape) - emits the preview wrapper body
// (written to the generated cache, .design-sync/.cache/previews/<Name>.tsx)
// for one component by IMPORTING THE STORY MODULE itself and
// exposing each story as a component. The whole module comes along - hooks,
// fixtures, local helper components - so a render that closes over
// story-local refs works as-is. Component identifiers still resolve to the SHIPPED bundle:
// lib/story-imports.mjs redirects package and relative component imports to
// window.<GLOBAL> at compile time, so the preview proves the real artifact.
//
// A component's stories may live in one module or be split across several
// (one-story-per-file layouts) - the wrapper imports every module that has a
// paired story; each story composes from its own module.
//
// The generated file carries the standard ownership marker; to hand-edit it
// (pin args, drop a story, inline a provider) copy it to
// .design-sync/previews/<Name>.tsx minus line 1 - owned copies win and
// re-syncs leave them alone. Fork seam: resolution policy lives in
// lib/story-imports.mjs.

import { relative } from 'node:path';
import { exportName } from './common.mjs';

// The composeStories-equivalent embedded in every wrapper. Storybook
// semantics, minimally: merged args (meta <- story), render precedence
// (story.render -> CSF2 function story -> meta.render -> meta.component), and
// meta+story decorators applied story-innermost with a minimal context
// carrying the standard field names (decorators that read ctx.kind/globals
// get empty-shaped values instead of crashing). Decorators needing real
// storybook runtime state degrade per-story to a cell error - grading
// residue, not a build failure.
const COMPOSE = `function compose(S: any, key: string) {
  const meta: any = S.default ?? {};
  const st: any = S[key];
  const args: any = { ...(meta.args ?? {}), ...(st && st.args ? st.args : {}) };
  // Storybook resolves argTypes.mapping (control value -> real arg) before
  // rendering; mirror that so mapped args don't render raw.
  const at: any = { ...(meta.argTypes ?? {}), ...(st && st.argTypes ? st.argTypes : {}) };
  for (const k of Object.keys(args)) {
    const m = at[k] && at[k].mapping;
    if (m && typeof m === 'object' && args[k] in m) args[k] = m[args[k]];
  }
  const title: string = typeof meta.title === 'string' ? meta.title : '';
  const ctx: any = {
    args, name: key, title, kind: title, id: '', componentId: '',
    globals: {}, viewMode: 'story',
    parameters: (st && st.parameters) ?? meta.parameters ?? {},
  };
  let render: (() => any) | null = null;
  if (st && typeof st.render === 'function') render = () => st.render(args, ctx);
  else if (typeof st === 'function') render = () => st(args, ctx);
  else if (typeof meta.render === 'function') render = () => meta.render(args, ctx);
  else {
    const C = (st && st.component) || meta.component;
    if (C) render = () => React.createElement(C, args);
  }
  if (!render) return () => null;
  // [].concat: a single function is legal CSF decorator shorthand. A
  // decorator returning undefined (stubbed addon) falls through to the inner
  // render \u2014 otherwise one unrecognized addon blanks the cell silently.
  const decorators: any[] = ([] as any[]).concat((st && st.decorators) ?? []).concat(meta.decorators ?? []);
  return decorators.reduce((inner: any, dec: any) => () => {
    const out = dec(inner, ctx);
    return out === undefined ? inner() : out;
  }, render);
}`;

// Generate the preview .tsx body for one component - or null when nothing
// paired, in which case no wrapper is written and the html shows the floor
// card (the same floor as a wrapper that fails to compile). Pairing failures
// are loud and fixable, so the floor card is the only fallback.
export function generatePreviewSource(c, opts) {
  // Story-module tier: needs the story source path and at least one visible
  // story paired to a module export (pairing happens in source-storybook.mjs
  // - c.storyIds[].exportKey).
  const skipSet = new Set(opts.skip ?? []);
  const visible = (c.storyIds ?? []).filter((s) => !skipSet.has(s.id));
  const paired = visible.filter((s) => s.exportKey);
  if (!c.storySrc || paired.length === 0) {
    if (c.storySrc && visible.length > 0) {
      console.error(`  (preview: ${c.name} \u2014 no story exports paired (storyName overrides?); showing the floor card)`);
    }
    return null;
  }
  // Location-independent import: `@ds-stories/<path relative to the repo
  // root>` (forward slashes for machine portability), resolved by the
  // story-imports plugin set. A relative spec would bake in the wrapper's
  // directory depth - and the promote flow copies wrappers from the
  // generated cache into .design-sync/previews/ (one level shallower), so
  // the same file must compile from either home. One import per distinct
  // story module, in first-paired order; S is the first (and for
  // single-module components the only) one.
  const toSpec = (p) => {
    const rel = relative(process.cwd(), p).replace(/\\/g, '/');
    return JSON.stringify(`@ds-stories/${rel}`.replace(/\.[cm]?[jt]sx?$/, ''));
  };
  const modVars = new Map(); // story source path -> import identifier
  const modVarFor = (p) => {
    if (!modVars.has(p)) modVars.set(p, modVars.size === 0 ? 'S' : `S${modVars.size + 1}`);
    return modVars.get(p);
  };
  // Emitted export names are PascalCased via exportName (the html mount loop
  // only renders /^[A-Z]/ exports; CSF allows camelCase keys) - compare's
  // squash pairing is case-insensitive, so pairing is unaffected. compose()
  // still receives the RAW module key. Squash collisions (two index stories
  // pairing to one export of the same module, e.g. via a storyName override)
  // emit once.
  // Each story records the EXACT export name its cell is emitted under
  // (s.emitted, carried into the stories-map) - labels are deduped when the
  // same key appears in several modules ("Default" + "Default2"), so compare
  // must pair on the emitted label, not a fuzzy match of the raw key.
  const seen = new Set();
  const used = new Set();
  const lines = [];
  for (const s of paired) {
    const mod = modVarFor(s.storySrc ?? c.storySrc);
    const dupKey = `${mod}:${s.exportKey}`;
    if (seen.has(dupKey)) {
      console.error(`  (preview: ${c.name} \u2014 story "${s.name}" pairs to already-emitted export ${s.exportKey}; skipping duplicate)`);
      continue;
    }
    seen.add(dupKey);
    const label = exportName(s.exportKey, used);
    s.emitted = label;
    lines.push(`export const ${label} = /* ${s.name} */ compose(${mod}, ${JSON.stringify(s.exportKey)});`);
  }
  const imports = [...modVars.entries()]
    .map(([p, v]) => `import * as ${v} from ${toSpec(p)};`)
    .join('\n');
  return `import * as React from 'react';
${imports}

${COMPOSE}

${lines.join('\n')}
`;
}

